css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-hsplit .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.9em 1.5em;border-radius:var(--radius);font:700 .95em var(--font-body);text-decoration:none;border:1.5px solid var(--primary);background:var(--primary);color:var(--on-primary);cursor:pointer;transition:transform calc(.25s/var(--speed)),box-shadow calc(.25s/var(--speed))}
.fx-hsplit .btn:hover{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-hsplit .btn.ghost{background:transparent;color:var(--primary)}
.fx-hsplit .btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-hsplit{display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:4em;padding:4em max(5vw,1.5em);background:var(--surface);overflow:hidden}
.fx-hsplit .copy{display:grid;gap:1.4em;justify-items:start;max-width:34em}
.fx-hsplit .copy>*{animation:fxhs-in calc(.8s/var(--speed)) cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i,0)*90ms/var(--speed))}
.fx-hsplit .eye{display:inline-flex;align-items:center;gap:.6em;padding:.4em .9em;border:1px solid var(--border);border-radius:999px;font-size:.78em;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--text)}
.fx-hsplit .eye i{width:.55em;height:.55em;border-radius:50%;background:var(--accent)}
.fx-hsplit h1{font-size:clamp(2.4em,5.2vw,4.4em);line-height:1.04}
.fx-hsplit h1 em{font-style:italic;color:var(--primary)}
.fx-hsplit .lead{font-size:1.15em;opacity:.72;max-width:30em}
.fx-hsplit .cta{display:flex;gap:.8em;flex-wrap:wrap}
.fx-hsplit .proof{display:flex;align-items:center;gap:.9em;font-size:.88em;opacity:.8}
.fx-hsplit .faces{display:flex}.fx-hsplit .faces i{width:2.3em;height:2.3em;border-radius:50%;border:2px solid var(--surface);margin-left:-.6em;background:linear-gradient(135deg,var(--primary),var(--accent))}
.fx-hsplit .faces i:first-child{margin-left:0}.fx-hsplit .faces i:nth-child(2){background:linear-gradient(135deg,var(--accent),var(--secondary))}.fx-hsplit .faces i:nth-child(3){background:linear-gradient(135deg,var(--secondary),var(--primary))}
.fx-hsplit .vis{position:relative;animation:fxhs-in calc(1s/var(--speed)) cubic-bezier(.2,.8,.2,1) .2s both}
.fx-hsplit .vis .fx-art{aspect-ratio:4/5;max-height:72vh;width:100%;border-radius:calc(var(--radius)*2.2)}
.fx-hsplit .float{position:absolute;display:flex;align-items:center;gap:.8em;padding:.9em 1.1em;border-radius:var(--radius);background:var(--surface);color:var(--text);border:1px solid var(--border);box-shadow:0 24px 40px -22px rgba(0,0,0,.45);font-size:.88em;animation:fxhs-bob calc(6s/var(--speed)) ease-in-out infinite}
.fx-hsplit .float b{display:block;font:600 1.5em/1 var(--font-heading)}.fx-hsplit .float span{opacity:.65;font-size:.9em}
.fx-hsplit .f1{left:-8%;bottom:12%}.fx-hsplit .f2{right:-4%;top:9%;animation-delay:-3s}
.fx-hsplit .f2 .dot{width:2.2em;height:2.2em;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;font-weight:700}
@keyframes fxhs-in{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@keyframes fxhs-bob{50%{transform:translateY(-10px)}}
@media(max-width:860px){.fx-hsplit{grid-template-columns:1fr;gap:2.4em;padding:3em 1.25em}.fx-hsplit .vis .fx-art{aspect-ratio:4/3}.fx-hsplit .f1{left:2%}.fx-hsplit .f2{right:2%}}
@media(prefers-reduced-motion:reduce){.fx-hsplit .copy>*,.fx-hsplit .vis,.fx-hsplit .float{animation:none}}
/* touch: :hover mirrored as .is-tap */
.fx-hsplit .btn.is-tap{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
